  const rows=[];
  let x=3;
  for(let k=0;k<4;k++){
    const f=x*x-2, df=2*x, xn=x-f/df;
    rows.push([k,+x.toFixed(4),+f.toFixed(4),+df.toFixed(4),+xn.toFixed(4)]);
