function run(){
  const f=(x)=>x[0]*x[0]+2*x[1]*x[1];
  const g=(x)=>[2*x[0],4*x[1]];
  const r4=(v)=>Array.isArray(v)?v.map(r4):+Number(v).toFixed(4);
  const columns=["k","x_k","f(x_k)","||grad||","step","H_k"];
  const rows=[]; let x=[4,1]; let H=[[1,0],[0,1]];
  for(let k=0;k<4;k++){
    const fx=f(x), gx=g(x), gn=Math.hypot(gx[0],gx[1]);
    const Hy=[H[0][0]*gx[0]+H[0][1]*gx[1],H[1][0]*gx[0]+H[1][1]*gx[1]];
    const p=[-Hy[0],-Hy[1]];
    let a=1,j=0;
    while(j<20 && f([x[0]+a*p[0],x[1]+a*p[1]]) > fx+1e-4*a*(gx[0]*p[0]+gx[1]*p[1])){a/=2;j++;}
    const xn=[x[0]+a*p[0],x[1]+a*p[1]];
    const s=[xn[0]-x[0],xn[1]-x[1]];
    const gy=g(xn), y=[gy[0]-gx[0],gy[1]-gx[1]];
    const ys=y[0]*s[0]+y[1]*s[1], rho=1/ys;
    const yHy=y[0]*Hy[0]+y[1]*Hy[1];
    rows.push([k,r4(x),r4(fx),r4(gn),r4(a),[r4(H[0]),r4(H[1])]]);
    for(let i=0;i<2;i++)for(let l=0;l<2;l++)
      H[i][l]=H[i][l]+rho*s[i]*s[l]+rho*rho*yHy*s[i]*s[l]-rho*(s[i]*Hy[l]+Hy[i]*s[l]);
    x=xn;
  }
  return {columns,rows,answer:"x ≈ ("+r4(x[0])+", "+r4(x[1])+"), f ≈ "+r4(f(x))+" — the minimum is at (0,0)"};
}

function run(){
  const A=[[1,1,0],[1,0,1]];
  const columns=["k","a_k","a_k · u_(k-1)","u_k"];
  const U=[]; const rows=[];
  for(let k=0;k<A.length;k++){
    let v=A[k].slice(); let dot=null;
    for(const u of U){ dot=u[0]*v[0]+u[1]*v[1]+u[2]*v[2]; v=v.map((x,i)=>x-dot*u[i]); }
    const n=Math.hypot(v[0],v[1],v[2]);
    const u=v.map(x=>x/n);
    U.push(u);
    rows.push([k+1,A[k],dot===null?"—":+dot.toFixed(4),u.map(x=>+x.toFixed(4))]);
  }
  const dd=U[0][0]*U[1][0]+U[0][1]*U[1][1]+U[0][2]*U[1][2];
  return {columns,rows,answer:"u1·u2 = "+dd.toFixed(4)+" — orthogonal (and each |u_k| = 1)"};
}
